
UPDATE public.outreach_templates
SET body = E'Hi {{contact_name}},\n\nJust a quick follow-up on my last email.\n\nEventbrite holds your funds until after your event ends. With TeeVents, every registration settles directly in your own Stripe account at the moment of checkout — TeeVents never holds your money. Stripe then pays out to your bank on its normal schedule (typically 2 business days, 2–7 days for brand-new Stripe accounts).\n\nThat means you can use the registration money you''ve already collected to pay course deposits, printing, signage, and other up-front costs — instead of fronting everything out of your own pocket.\n\nEventbrite has no live leaderboard, no sponsor portal, and no volunteer check-in. TeeVents has all of that built in.\n\nOur pricing is simple: a 5% platform fee on each transaction (Stripe''s processing fee is separate, just like Eventbrite).\n\nSee the side-by-side comparison:\nhttps://www.teevents.golf/compare/eventbrite-vs-teevents\n\nIf you''re open to it, I''d love to show you how it works in a 15-min demo.\n\nhttps://calendly.com/teevents-golf/demo\n\nEither way, best of luck with your tournament.\n\n{{sender_name}}\nTeeVents Golf'
WHERE id = '33bdca6c-947a-475c-844f-b4b8d7e136a2';

UPDATE public.outreach_templates
SET body = E'Hi {{contact_name}},\n\nI see you''re using Eventbrite for {{tournament_name}}.\n\nEventbrite is great for concerts, but golf tournaments need more:\n❌ Live leaderboards\n❌ Hole sponsors\n❌ Volunteer check-in\n❌ Pairings & tee sheets\n\nAnd two big frustrations you''ve probably felt:\n\n1. Juggling spreadsheets for things Eventbrite doesn''t handle.\n2. Waiting for funds – Eventbrite holds your money until after the event.\n\nTeeVents was built specifically for golf tournaments by golf tournament organizers:\n\n✅ Live leaderboard (embed on your site)\n✅ Sponsor portal with asset delivery\n✅ Volunteer QR check-in & shift scheduling\n✅ Drag-and-drop pairings\n✅ Funds direct to your Stripe at checkout — no waiting until after the event\n\nWhy that matters:\nCourses often require deposits. Signage, printing, and food need to be paid before the event. With TeeVents, every registration settles in your own Stripe account at the moment of checkout (TeeVents only takes a 5% application fee). Stripe then pays out to your bank on its normal rolling schedule — typically 2 business days, and 2–7 business days for brand-new Stripe accounts during Stripe''s initial review.\n\nPricing is simple: a 5% platform fee per transaction (Stripe''s processing fee is separate).\n\nSee the full comparison here:\nhttps://www.teevents.golf/compare/eventbrite-vs-teevents\n\nI''d be happy to show you how it works in a quick 15-min demo.\n\nhttps://calendly.com/teevents-golf/demo\n\nTo a smoother tournament,\n\n{{sender_name}}\nTeeVents Golf'
WHERE id = '507bebf1-2ba0-422f-b43f-c059da78adcb';
